UPDATE agent_runtime_execution_runs SET 
WHERE tenant_id=#{row.tenantId} AND run_id=#{row.runId} AND revision=#{expected}
  AND phase='READY' AND NOT cancelled AND lease_claim_id=#{row.leaseClaimId}
  AND lease_worker_id=#{row.leaseWorkerId} AND fence=#{row.fence}
  AND runtime_lease_valid(lease_until_second,lease_until_nano)=1

UPDATE agent_runtime_execution_runs SET 
WHERE tenant_id=#{row.tenantId} AND run_id=#{row.runId} AND revision=#{expected}
  AND phase='READY' AND NOT cancelled AND lease_claim_id=#{row.leaseClaimId}
  AND lease_worker_id=#{row.leaseWorkerId} AND fence=#{row.fence}
  AND runtime_lease_valid(lease_until_second,lease_until_nano)=1

UPDATE agent_runtime_execution_runs SET 
WHERE tenant_id=#{row.tenantId} AND run_id=#{row.runId} AND revision=#{expected}
  AND phase='READY' AND NOT cancelled AND current_action_id IS NULL AND batch_source_attempt IS NULL AND waiting_action_id IS NULL
  AND lease_claim_id=#{lease.claimId} AND lease_worker_id=#{lease.workerId} AND fence=#{lease.fencingToken}
  AND runtime_lease_valid(lease_until_second,lease_until_nano)=1

mapper.select:
SELECT tenant_id,reference,schema_id,canonical_json FROM agent_runtime_execution_materials
WHERE tenant_id=#{tenant} AND reference IN
#{reference}

mapper.update:
UPDATE agent_runtime_execution_attempts SET result_kind=#{resultKind},result_ref=#{resultRef},uncertainty_ref=#{uncertaintyRef},feedback_ref=#{feedbackRef},
    external_operation=#{externalOperation},adopted=#{adopted}
WHERE tenant_id=#{tenantId} AND run_id=#{runId} AND attempt_id=#{attemptId}

UPDATE agent_runtime_execution_waits SET continuation_attempt=#{continuationAttempt}
WHERE tenant_id=#{tenantId} AND run_id=#{runId} AND action_id=#{actionId} AND generation=#{generation}
  AND input_id IS NOT NULL AND continuation_attempt IS NULL
  AND kind IN ('TOOL','WORKFLOW') AND consumed_revision IS NULL

UPDATE agent_runtime_execution_waits SET consumed_revision=#{consumedRevision}
WHERE tenant_id=#{tenantId} AND run_id=#{runId} AND action_id=#{actionId} AND generation=#{generation}
  AND kind IN ('HUMAN','DELEGATION','PLAN') AND input_id IS NOT NULL AND consumed_revision IS NULL AND continuation_attempt IS NULL

mapper.select:
SELECT count(*) FROM agent_runtime_execution_runs
WHERE tenant_id=#{tenant} AND phase<>'FINISHED' AND session_id IN
#{session}

SELECT  FROM agent_runtime_execution_runs
WHERE tenant_id=#{tenant} AND session_id=#{session}
ORDER BY created_second DESC,created_nano DESC,run_id DESC LIMIT 1

SELECT  FROM agent_runtime_execution_events
WHERE tenant_id=#{tenant} AND session_id=#{session} AND (type='tool')=#{tool}
ORDER BY event_sequence DESC LIMIT #{limit}
